         {
+            // Double check conditions now that we have obtained the lock
+            if ( m_disposed )
+            {
+                log( LogService.LOG_DEBUG, &quot;ActivateInternal: disposed&quot;,
+                        null );
+                return;
+            }
+            if ( m_activated ) {
+                log( LogService.LOG_DEBUG, &quot;ActivateInternal: already activated&quot;,
+                        null );
+                return;
